      cpp: `#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nlong long mergeSort(vector<long long>& a, int l, int r) {\n    if (l >= r) return 0;\n    int mid = l + (r - l) / 2;\n    long long count = mergeSort(a, l, mid) + mergeSort(a, mid + 1, r);\n    int j = mid + 1;\n    for (int i = l; i <= mid; i++) {\n        while (j <= r && a[i] > 2LL * a[j]) j++;\n        count += (j - (mid + 1));\n    }\n    inplace_merge(a.begin() + l, a.begin() + mid + 1, a.begin() + r + 1);\n    return count;\n}\nint main() {\n    int n; if (!(cin >> n)) return 0;\n    vector<long long> a(n); for (int i = 0; i < n; i++) cin >> a[i];\n    cout << mergeSort(a, 0, n - 1) << "\\n";\n    return 0;\n}`,
