async function seed() {
  try {
    console.log(`Connecting to MongoDB...`);
    await mongoose.connect(MONGO_URI);
    console.log(`Connected successfully!`);

    let insertedCount = 0;
    let updatedCount = 0;

    for (const prob of ARRAY_50_PROBLEMS) {
      const existing = await CodingProblem.findOne({ title: prob.title });
      if (existing) {
        await CodingProblem.findByIdAndUpdate(existing._id, prob);
        updatedCount++;
      } else {
        await CodingProblem.create(prob);
        insertedCount++;
      }
    }

    console.log(
      `Seeding complete! Inserted: ${insertedCount}, Updated: ${updatedCount}, Total: ${ARRAY_50_PROBLEMS.length}`
    );
    process.exit(0);
  } catch (err) {
    console.error("Seeding error:", err);
    process.exit(1);
  }
}

seed();
